const state={rivers:[],places:[],states:[],cities:[],selectedCity:null,cityStateContext:null,catalog:true,topic:"rivers",topicQuery:"",stateSelected:null,stateBorders:true,indiaCountryBorders:true,worldBorders:true,sidebarWidth:null,sidebarResize:null,land:[],worldLand:[],worldPlaces:[],worldTopic:"countries",worldCatalog:true,worldContinent:false,worldTopicQuery:"",edits:{},editTarget:null,originals:{},worldFeatureSelected:null,southQuery:"",southGroup:"all",worldQuery:"",worldRegion:"all",worldSelected:null,worldSidebar:false,indiaSidebar:false,worldLayers:false,indiaLayers:false,scope:"india",mode:"explore",group:"all",query:"",selected:null,detail:false,labels:true,session:null,history:{},timer:null,view:{x:0,y:0,w:1000,h:900},drag:null,storageOK:true};
const shuffle=values=>{const a=[...values];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
