function loadLocal(){try{const saved=JSON.parse(localStorage.getItem(KEY)||"{}");if(saved&&typeof saved==="object"){state.history=saved.history&&typeof saved.history==="object"?saved.history:{};state.edits=saved.edits&&typeof saved.edits==="object"?saved.edits:{};loadMapSettings(saved.mapSettings);document.documentElement.dataset.theme=saved.theme==="light"?"light":"dark";}}catch{state.storageOK=false;}updateThemeButton();}
