function announce(message){$("announcement").textContent=message;}
function setView(v,layout=true){state.view=v;$("atlas").setAttribute("viewBox",`${v.x} ${v.y} ${v.w} ${v.h}`);const scale=markerScale();['current-warm','current-cold'].forEach(id=>{$(id).setAttribute('markerWidth',3*scale);$(id).setAttribute('markerHeight',3*scale);});document.querySelectorAll('.place-marker').forEach(el=>el.setAttribute('transform',`translate(${el.dataset.x} ${el.dataset.y}) scale(${scale})`));updateMapLabelVisibility();if(layout)layoutPlaceLabels();document.querySelectorAll('.river-label').forEach(el=>el.setAttribute('font-size',(el.classList.contains('active')?14:12)*scale));}
function zoomedView(v,factor,p,scope=state.scope){const w=Math.max(scope==='world'?40:90,Math.min(scope==='world'?1500:1600,v.w*factor)),ratio=w/v.w;return {x:p[0]-(p[0]-v.x)*ratio,y:p[1]-(p[1]-v.y)*ratio,w,h:v.h*ratio};}
