 applySidebarWidth();const world=state.scope==='world',open=world?state.worldSidebar:state.indiaSidebar,layers=world?state.worldLayers:state.indiaLayers;
 const sidebar=document.querySelector('.sidebar');if(sidebar)sidebar.inert=!open;
 document.documentElement.dataset.mapScope=state.scope;document.documentElement.dataset.worldSidebar=String(open);
 $("world-sidebar-toggle").hidden=false;$("world-sidebar-toggle").textContent=open?'‹':'›';$("world-sidebar-toggle").setAttribute('aria-expanded',String(open));$("world-sidebar-toggle").setAttribute('aria-label',(open?'Fold ':'Open ')+(world?'world sidebar':'India topics'));
 $("world-layers-toggle").hidden=false;$("world-layers").hidden=true;$('symbol-legend').hidden=!layers;renderSymbolLegend();$("world-layers-toggle").setAttribute('aria-pressed',String(layers));$('world-layers-toggle').setAttribute('aria-label',layers?'Hide map key':'Show map key');$('world-layers-toggle').setAttribute('aria-expanded',String(layers));
