 if(state.scope==="world"){renderWorldMap();return;}renderLand();$("atlas").setAttribute("aria-label",state.catalog?"India states and union territories":state.topic==="mountains"?"India mountains, peaks and passes":"India physical geography and river routes");$("atlas-title").textContent=state.catalog?"India states and union territories":state.topic==="mountains"?"Mountains, peaks and passes of India":"River routes of the Indian subcontinent";$("focus-river").hidden=false;$("map-attribution-note").textContent='Natural Earth · © OpenStreetMap · geoBoundaries';$("map-legend").innerHTML='<span><i></i>River route</span><span><i class="selected"></i>Selected river</span>';$("map-source").textContent="Map sources & credits";
 const s=state.session,quizzing=!!s&&!s.done,current=quizzing?river(s.ids[s.index]):state.catalog?null:river(state.selected),hidden=quizzing&&!s.revealed,visible=new Set(visibleItems().map(r=>r.id));
