 $("sidebar-content").innerHTML=rows.length?`<div class="river-list">${rows.map((r,i)=>`<button class="river-row${r.id===state.selected?' active':''}" data-select="${r.id}"><span class="river-number">${String(i+1).padStart(2,'0')}</span><span><span class="river-name">${esc(r.name)}</span><span class="river-meta">${esc(r.parent?`Tributary of ${river(r.parent)?.name||r.parent}`:GROUPS[r.group])}</span></span><span class="row-arrow" aria-hidden="true">↗</span></button>`).join("")}</div>`:'<div class="empty">No rivers match your search.<br>Try a place name, source or drainage group.</div>';
