 $("sidebar-content").innerHTML=`<article class="detail"><button class="back-link" data-action="back">← All matching rivers</button><h2>${esc(r.name)}</h2><p class="detail-group">${esc(GROUPS[r.group])}</p><dl><div class="fact"><dt>${r.kind==="point"?"Location":"Source"}</dt><dd>${esc(r.source)}</dd></div><div class="fact"><dt>${r.kind==="point"?"Feature type":"Joins / drains into"}</dt><dd>${esc(r.mouth)}</dd></div><div class="fact"><dt>Course at a glance</dt><dd>${esc(r.route)}</dd></div></dl><div class="note"><p class="eyebrow">MAKE THE CONNECTION</p>${esc(r.note)}</div>${r.kind==="point"?`<p class="coordinate-note">Approximate ${r.group==="range"?"representative range":"location"} marker · <a href="${esc(r.coordinateSource)}" target="_blank" rel="noopener">Coordinate source ↗</a></p>`:renderTributaries(r)}<button class="edit-place-button" data-edit="${esc(r.id)}">✎ Edit information</button><div class="detail-actions"><button class="secondary" data-action="focus">⌖ Focus river</button><button class="primary" data-action="practice-group">Practise this group</button></div></article>`;
