function renderWorldSidebar(){if(state.worldCatalog){renderWorldCatalog();return;}if(state.mode!=='explore'){if(!state.session)renderSetup();else if(state.session.done)renderSummary();else renderQuiz();return;}const rows=state.worldQuery.trim()?globalSearch('world',state.worldQuery):worldVisible();$("sidebar-content").innerHTML='<div class="world-sidebar"><label class="search-wrap"><span aria-hidden="true">⌕</span><input id="world-place-search" type="search" placeholder="Search places or notes…" aria-label="Search world places" value="'+esc(state.worldQuery)+'"></label><label class="filter-label" for="world-feature-group">FEATURE TYPE</label><select id="world-feature-group">'+worldGroupOptions()+'</select>'+worldRegionControl('world-region')+'<div class="list-heading"><span id="world-list-count">'+rows.length+(state.worldQuery.trim()?' RESULTS':' PLACES')+'</span></div><div id="world-place-list">'+worldPlaceRows()+'</div></div>';}
