function renderScope(){const world=state.scope==='world',catalog=world?state.worldCatalog:state.catalog;$("scope-eyebrow").textContent=world?'GEOGRAPHY / WORLD':'GEOGRAPHY / INDIA';$("scope-title").innerHTML=world?(catalog?'World atlas':esc(state.worldContinent?state.worldRegion:WORLD_TOPICS[state.worldTopic]?.name||'World places'))+'<span>.</span>':state.catalog?'India atlas<span>.</span>':state.topic==='mountains'?'Mountains, peaks &amp; passes<span>.</span>':state.topic==='all'?'All India places<span>.</span>':'Rivers &amp; drainage<span>.</span>';$("scope-intro").textContent=catalog?'Explore by topic.':'';$("learning-modes").hidden=catalog;document.querySelectorAll('[data-scope]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.scope===state.scope)));}
function renderSidebar(){const world=state.scope==='world';$("explorer-controls").hidden=world||state.mode!=="explore"||state.topic!=="rivers";renderScope();$("topics-back").hidden=world||state.catalog;$("learning-modes").hidden=world||state.catalog;if(world){$("topics-back").hidden=state.worldCatalog;$("topics-back").textContent="← All World topics";$("learning-modes").hidden=state.worldCatalog;document.querySelectorAll("[data-mode]").forEach(b=>b.setAttribute("aria-pressed",String(b.dataset.mode===state.mode)));renderWorldSidebar();return;}$("topics-back").textContent="← All India topics";if(state.catalog){$("explorer-controls").hidden=true;renderCatalog();return;}$("system").innerHTML=groupOptions();$("system").value=state.group;$("search").placeholder="Search names, regions or notes…";const exploring=state.mode==='explore';document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.mode===state.mode));if(exploring){if(state.detail)renderDetail();else if(state.topic==='rivers')renderList();else renderPhysicalList();}else if(!state.session)renderSetup();else if(state.session.done)renderSummary();else renderQuiz();}
function stopTimer(){if(state.timer){clearInterval(state.timer);state.timer=null;}}
function setMode(mode){stopTimer();if(state.scope==='india')state.catalog=false;state.mode=mode;state.session=null;state.detail=false;if(state.scope==="world"){state.worldCatalog=false;state.worldSidebar=true;}else state.indiaSidebar=true;updateWorldLayout();renderSidebar();renderMap();}
function setScope(scope){if(!["india","world"].includes(scope)||scope===state.scope)return;cancelViewMotion();const panel=document.querySelector('.map-panel');if(panel?.animate&&!reducedMotion())panel.animate([{opacity:.25},{opacity:1}],{duration:320,easing:'ease-out'});stopTimer();state.selectedCity=null;state.cityStateContext=null;state.scope=scope;if(scope==="world"&&state.worldCatalog)state.worldSidebar=true;state.mode="explore";state.session=null;state.detail=false;state.drag=null;updateWorldLayout();resetMap();if(scope==='world'&&!state.worldCatalog&&state.worldTopic!=='countries'&&state.worldTopic!=='all')fitWorldTopic();renderSidebar();renderMap();announce(scope==="world"?"World map workspace opened.":"India river atlas opened.");}
function startSession(ids){stopTimer();if(state.scope==='india')state.catalog=false;const timerEnabled=$("timer-enabled")?.checked||false,pool=ids||activeItems().filter(matchesGroup).map(r=>r.id);if(!pool.length)return;state.session={mode:state.mode,ids:shuffle(pool).slice(0,10),index:0,revealed:false,done:false,results:[],timed:timerEnabled,seconds:30,options:[]};prepareQuestion();}
function prepareQuestion(){const s=state.session,target=river(s.ids[s.index]);s.revealed=false;s.choice=null;s.seconds=30;s.timedOut=false;const related=activeItems().filter(r=>r.id!==target.id&&r.group===target.group),other=activeItems().filter(r=>r.id!==target.id&&!related.includes(r));s.options=shuffle([target,...[...shuffle(related),...shuffle(other)].slice(0,3)]).map(r=>r.id);state.selectedCity=null;state.cityStateContext=null;state.stateSelected=null;state.worldSelected=null;state.worldFeatureSelected=null;resetMap();if(state.scope==="world")focusWorldStudy(target);renderSidebar();renderMap();startTimer();}
